 39→    private static final MemorySerializer<Long> LONG_DOC_ID_SERIALIZER = new MemorySerializer<>() {
 40→        @Override
 41→        public MemorySegment serialize(Long value) {
 42→            byte[] bytes = new byte[8];
 43→            long v = value;
 44→            for (int i = 7; i >= 0; i--) {
 45→                bytes[i] = (byte) (v & 0xFF);
 46→                v >>>= 8;
 47→            }
 48→            return MemorySegment.ofArray(bytes);
 49→        }
 50→
 51→        @Override
 52→        public Long deserialize(MemorySegment segment) {
 53→            byte[] bytes = segment.toArray(ValueLayout.JAVA_BYTE);
 54→            long v = 0L;
 55→            for (byte b : bytes)
 56→                v = (v << 8) | (b & 0xFFL);
 57→            return v;
 58→        }
 59→    };
