348→        // Key namespace prefix bytes
349→        private static final byte CENTROID_PREFIX = 0x00;
350→        private static final byte POSTING_PREFIX = 0x01;
351→        private static final byte REVERSE_PREFIX = 0x02;
352→
353→        // Scan bounds: [CENTROID_PREFIX, POSTING_PREFIX) covers all centroid keys
354→        private static final MemorySegment CENTROID_SCAN_START = MemorySegment
355→                .ofArray(new byte[]{ CENTROID_PREFIX });
356→        private static final MemorySegment CENTROID_SCAN_END = MemorySegment
357→                .ofArray(new byte[]{ POSTING_PREFIX });
358→
359→        private final LsmTree lsmTree;
360→        private final MemorySerializer<D> docIdSerializer;
361→        private final int dimensions;
362→        private final SimilarityFunction similarityFunction;
363→        private final int numClusters;
364→        private final int nprobe;
365→        private final VectorPrecision precision;
366→
367→        private IvfFlat(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
368→                SimilarityFunction similarityFunction, int numClusters, int nprobe,
369→                VectorPrecision precision) {
370→            assert lsmTree != null;
371→            assert docIdSerializer != null;
372→            assert dimensions > 0;
373→            assert similarityFunction != null;
374→            assert numClusters > 0;
375→            assert nprobe > 0;
376→            assert precision != null;
377→            this.lsmTree = lsmTree;
378→            this.docIdSerializer = docIdSerializer;
379→            this.dimensions = dimensions;
380→            this.similarityFunction = similarityFunction;
381→            this.numClusters = numClusters;
382→            this.nprobe = nprobe;
383→            this.precision = precision;
384→        }
385→
386→        @Override
387→        public VectorPrecision precision() {
388→            return precision;
389→        }
390→
391→        @Override
392→        public void index(D docId, float[] vector) throws IOException {
393→            Objects.requireNonNull(docId, "docId must not be null");
394→            Objects.requireNonNull(vector, "vector must not be null");
395→            if (vector.length != dimensions) {
396→                throw new IllegalArgumentException(
397→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
398→            }
399→
400→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
401→            byte[] vectorBytes = encodeVector(vector, precision);
402→
403→            int centroidId = assignCentroid(vector);
404→
405→            // Store posting: [0x01][centroid_id][docId] → vector
406→            lsmTree.put(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)),
407→                    MemorySegment.ofArray(vectorBytes));
408→
409→            // Store reverse lookup: [0x02][docId] → centroid_id (4 bytes BE)
410→            lsmTree.put(MemorySegment.ofArray(reverseKey(docIdBytes)),
411→                    MemorySegment.ofArray(encodeCentroidId(centroidId)));
412→        }
413→
414→        @Override
415→        public void remove(D docId) throws IOException {
416→            Objects.requireNonNull(docId, "docId must not be null");
417→
418→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
419→            byte[] revKey = reverseKey(docIdBytes);
420→
421→            Optional<MemorySegment> revOpt = lsmTree.get(MemorySegment.ofArray(revKey));
422→            if (revOpt.isEmpty())
423→                return; // not indexed
424→
425→            int centroidId = decodeCentroidId(revOpt.get().toArray(ValueLayout.JAVA_BYTE), 0);
426→
427→            lsmTree.delete(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)));
428→            lsmTree.delete(MemorySegment.ofArray(revKey));
429→        }
