431→        @Override
432→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
433→                throws IOException {
434→            Objects.requireNonNull(query, "query must not be null");
435→            if (query.length != dimensions) {
436→                throw new IllegalArgumentException(
437→                        "query.length=" + query.length + " != dimensions=" + dimensions);
438→            }
439→            if (topK <= 0)
440→                throw new IllegalArgumentException("topK must be > 0");
441→
442→            // Load all centroids
443→            List<float[]> centroidVecs = new ArrayList<>();
444→            List<Integer> centroidIds = new ArrayList<>();
445→            Iterator<Entry> centIt = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
446→            while (centIt.hasNext()) {
447→                Entry entry = centIt.next();
448→                if (!(entry instanceof Entry.Put put))
449→                    continue;
450→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
451→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
452→                    continue;
453→                int cid = decodeCentroidId(key, 1);
454→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
455→                centroidVecs.add(cVec);
456→                centroidIds.add(cid);
457→            }
458→
459→            if (centroidVecs.isEmpty())
460→                return List.of();
461→
462→            // Score centroids, pick top nprobe
463→            int actualNprobe = Math.min(nprobe, centroidVecs.size());
464→            int[] nearestCentroidIds = topNCentroids(query, centroidVecs, centroidIds,
465→                    actualNprobe);
466→
467→            // Accumulate candidates from posting lists (min-heap to evict worst when over topK)
468→            PriorityQueue<ScoredCandidate> heap = new PriorityQueue<>(
469→                    Comparator.comparingDouble(ScoredCandidate::score)); // min at head for eviction
470→
471→            for (int cid : nearestCentroidIds) {
472→                byte[] postStart = postingKey(cid, new byte[0]);
473→                byte[] postEnd = postingEndKey(cid);
474→
475→                Iterator<Entry> postIt = lsmTree.scan(MemorySegment.ofArray(postStart),
476→                        MemorySegment.ofArray(postEnd));
477→
478→                while (postIt.hasNext()) {
479→                    Entry entry = postIt.next();
480→                    if (!(entry instanceof Entry.Put put))
481→                        continue; // skip tombstones
482→
483→                    byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
484→                    if (key.length <= 5 || key[0] != POSTING_PREFIX)
485→                        continue;
486→
487→                    byte[] docIdBytes = Arrays.copyOfRange(key, 5, key.length);
488→                    float[] vec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE),
489→                            dimensions);
490→                    float s = score(query, vec, similarityFunction);
491→
492→                    heap.add(new ScoredCandidate(docIdBytes, s));
493→                    if (heap.size() > topK)
494→                        heap.poll(); // evict worst
495→                }
496→            }
497→
498→            // Drain heap in descending order
499→            List<ScoredCandidate> sorted = new ArrayList<>(heap);
500→            sorted.sort((a, b) -> Float.compare(b.score(), a.score()));
501→
502→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>(sorted.size());
503→            for (ScoredCandidate c : sorted) {
504→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
505→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
506→            }
507→            return results;
508→        }
