        // Builder
        // -----------------------------------------------------------------------

        /** Builder for {@link LsmVectorIndex.IvfFlat}. */
        public static final class Builder<D> extends AbstractBuilder<D, Builder<D>> {

            private int numClusters = 256;
            private int nprobe = 8;

            public Builder<D> numClusters(int n) {
